[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

# Напоминание стиля на КАЖДЫЙ запрос (раньше шло раз в 4: свежесть важнее, цена ~120 токенов).
# Источник правил: ~/.claude/rules/ponyatno.md. Имя файла оставлено ради settings.json.
@{
    hookSpecificOutput = @{
        hookEventName     = 'UserPromptSubmit'
        additionalContext = 'Стиль владельцу: первая строка простыми словами - что случилось или прямой ответ, без кода, имён файлов и английских терминов. Просьба к владельцу только если она есть: блок «Жду от тебя:», нумерованный список, в каждом пункте действие и «чтобы <цель>»; варианты выбора маркерами, рекомендованный первым с пометкой «мой выбор»; «Как» только если действие не очевидно. Если ничего не нужно, об этом не писать ни словом. Имена, команды, номера строк - в конце, блоком «Детали». Термин расшифровать один раз. Строки «Соло», «Проверено» - простыми словами; «Проверено» только если проверка не проведена или нашла расхождение. ИТОГ ПОСЛЕ РАБОТЫ: один, 1-3 строки, он же первая строка; второго итога в конце нет; объяснённое до работы не повторять («раньше/теперь», цена, зачем). ССЫЛКИ: путь никогда в обратных кавычках и не голым, только [имя](относительный/путь); html для проверки - ещё блок powershell с Start-Process "полный путь".'
    }
} | ConvertTo-Json -Compress -Depth 5
